#pragma once

// Shared helpers for asset-import tests: synthetic GameCube discs built in memory at
// test time, and per-test temporary folders. Every disc here is synthetic (made-up
// names and generated bytes). No real disc data is used or committed (CLAUDE.md
// rule 1), and images are only ever written to the system temp folder.

#include <doctest/doctest.h>

#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <map>
#include <string>
#include <string_view>
#include <vector>

#ifdef _WIN32
#include <process.h>
#else
#include <unistd.h>
#endif

namespace mpt_test {

namespace fs = std::filesystem;

inline void put32(std::vector<std::byte>& image, std::size_t offset, std::uint32_t value) {
  image[offset] = std::byte(value >> 24);
  image[offset + 1] = std::byte((value >> 16) & 0xff);
  image[offset + 2] = std::byte((value >> 8) & 0xff);
  image[offset + 3] = std::byte(value & 0xff);
}

inline std::uint32_t get32(const std::vector<std::byte>& image, std::size_t offset) {
  return (std::to_integer<std::uint32_t>(image[offset]) << 24) | (std::to_integer<std::uint32_t>(image[offset + 1]) << 16) |
         (std::to_integer<std::uint32_t>(image[offset + 2]) << 8) | std::to_integer<std::uint32_t>(image[offset + 3]);
}

inline std::vector<std::byte> bytes_of(std::string_view text) {
  std::vector<std::byte> out(text.size());
  for (std::size_t i = 0; i < text.size(); ++i) out[i] = static_cast<std::byte>(text[i]);
  return out;
}

struct DiscSpec {
  std::string disc_id = "GMPE01";
  std::uint8_t version = 0;
  std::uint8_t disc_number = 0;
  std::map<std::string, std::string> files;  // path → contents; parent directories are implied
  std::vector<std::string> empty_dirs;
};

inline DiscSpec default_spec() {
  DiscSpec spec;
  spec.files = {
      {"opening.bnr", std::string(0x60, 'B')},
      {"data/board.bin", "synthetic board data"},
      {"data/sub/deep.bin", std::string(0x1234, 'D')},
      {"dll/placeholder_name_000.rel", "synthetic module"},
      {"zero.bin", ""},
  };
  spec.empty_dirs = {"empty"};
  return spec;
}

inline constexpr std::uint32_t kDolOffset = 0x2500;
inline constexpr std::uint32_t kFstOffset = 0x2800;

struct BuiltDisc {
  std::vector<std::byte> image;
  std::uint32_t entry_count = 0;
  std::uint32_t fst_size = 0;
  std::size_t entry_at(std::uint32_t index) const { return kFstOffset + std::size_t{index} * 12; }
  std::size_t strings_at() const { return entry_at(entry_count); }
  std::size_t name_at(std::uint32_t index) const { return strings_at() + (get32(image, entry_at(index)) & 0xFFFFFF); }
  std::uint32_t index_of(std::string_view name) const {
    for (std::uint32_t i = 1; i < entry_count; ++i) {
      const std::size_t at = name_at(i);
      if (std::string_view(reinterpret_cast<const char*>(image.data() + at), name.size()) == name &&
          image[at + name.size()] == std::byte{0}) {
        return i;
      }
    }
    FAIL("no entry named " << name);
    return 0;
  }
  // Overwrites an entry's name in place. The new name must not be longer.
  void rename(std::string_view old_name, std::string_view new_name) {
    const std::size_t at = name_at(index_of(old_name));
    REQUIRE(new_name.size() <= old_name.size());
    for (std::size_t i = 0; i <= old_name.size(); ++i) {
      image[at + i] = i < new_name.size() ? static_cast<std::byte>(new_name[i]) : std::byte{0};
    }
  }
};

struct Node {
  bool is_dir = true;
  std::string data;
  std::map<std::string, Node> children;
};

// Lays out a minimal disc: header, bi2, a tiny apploader, a one-section DOL, the
// FST and then the file data, with the image ending exactly at the last file.
inline BuiltDisc build_disc(const DiscSpec& spec) {
  Node root;
  auto insert = [&root](const std::string& path, bool is_dir, const std::string& data) {
    Node* node = &root;
    std::size_t start = 0;
    while (true) {
      const std::size_t slash = path.find('/', start);
      Node& child = node->children[path.substr(start, slash - start)];
      if (slash == std::string::npos) {
        child.is_dir = is_dir;
        child.data = data;
        return;
      }
      node = &child;
      start = slash + 1;
    }
  };
  for (const auto& [path, data] : spec.files) insert(path, false, data);
  for (const std::string& dir : spec.empty_dirs) insert(dir, true, {});

  struct Entry {
    bool is_dir;
    std::uint32_t name_offset;
    std::uint32_t a;
    std::uint32_t b;
    const std::string* data;
  };
  std::vector<Entry> entries{{true, 0, 0, 0, nullptr}};
  std::string strings;
  auto emit = [&](auto& self, const Node& dir, std::uint32_t dir_index) -> void {
    for (const auto& [name, child] : dir.children) {
      const auto index = static_cast<std::uint32_t>(entries.size());
      entries.push_back({child.is_dir, static_cast<std::uint32_t>(strings.size()), dir_index, 0, &child.data});
      strings += name;
      strings.push_back('\0');
      if (child.is_dir) {
        self(self, child, index);
        entries[index].b = static_cast<std::uint32_t>(entries.size());
      }
    }
  };
  emit(emit, root, 0);
  entries[0].b = static_cast<std::uint32_t>(entries.size());

  BuiltDisc built;
  built.entry_count = static_cast<std::uint32_t>(entries.size());
  built.fst_size = static_cast<std::uint32_t>(entries.size() * 12 + strings.size());
  std::uint32_t cursor = (kFstOffset + built.fst_size + 0xFF) & ~0xFFu;
  std::uint32_t image_end = cursor;
  for (Entry& e : entries) {
    if (e.is_dir || e.data == nullptr) continue;
    e.a = cursor;
    e.b = static_cast<std::uint32_t>(e.data->size());
    image_end = cursor + e.b;
    cursor = (image_end + 0x1F) & ~0x1Fu;
  }

  std::vector<std::byte>& img = built.image;
  img.assign(image_end, std::byte{0});
  for (std::size_t i = 0; i < 6; ++i) img[i] = static_cast<std::byte>(spec.disc_id[i]);
  img[6] = std::byte{spec.disc_number};
  img[7] = std::byte{spec.version};
  put32(img, 0x1C, 0xC2339F3D);
  const std::string_view name = "SYNTHETIC TEST DISC";
  for (std::size_t i = 0; i < name.size(); ++i) img[0x20 + i] = static_cast<std::byte>(name[i]);
  put32(img, 0x420, kDolOffset);
  put32(img, 0x424, kFstOffset);
  put32(img, 0x428, built.fst_size);
  put32(img, 0x42C, built.fst_size);

  put32(img, 0x2440 + 0x14, 0x60);  // apploader body size; it ends at 0x24C0
  put32(img, kDolOffset + 0x00, 0x100);  // text section 0 at DOL offset 0x100...
  put32(img, kDolOffset + 0x90, 0x40);   // ...of 0x40 bytes, so the DOL is 0x140 bytes
  for (std::size_t i = 0; i < 0x40; ++i) img[kDolOffset + 0x100 + i] = std::byte(0x60 + (i & 0x0F));

  for (std::size_t i = 0; i < entries.size(); ++i) {
    const Entry& e = entries[i];
    const std::size_t at = built.entry_at(static_cast<std::uint32_t>(i));
    put32(img, at, (e.is_dir ? 0x01000000u : 0u) | e.name_offset);
    put32(img, at + 4, e.a);
    put32(img, at + 8, e.b);
    if (!e.is_dir && e.data) {
      for (std::size_t j = 0; j < e.data->size(); ++j) img[e.a + j] = static_cast<std::byte>((*e.data)[j]);
    }
  }
  for (std::size_t i = 0; i < strings.size(); ++i) img[built.strings_at() + i] = static_cast<std::byte>(strings[i]);
  return built;
}

inline long long current_pid() {
#ifdef _WIN32
  return static_cast<long long>(_getpid());
#else
  return static_cast<long long>(getpid());
#endif
}

class TempDir {
 public:
  TempDir() {
    static int counter = 0;
    // The process ID keeps parallel test runs (ctest -j, two build trees) apart.
    path_ = fs::temp_directory_path() / ("mpt_gc_test_" + std::to_string(current_pid()) + "_" +
                                         std::to_string(reinterpret_cast<std::uintptr_t>(this)) + "_" +
                                         std::to_string(counter++));
    fs::remove_all(path_);
    fs::create_directories(path_);
  }
  ~TempDir() {
    std::error_code ec;
    fs::remove_all(path_, ec);
  }
  const fs::path& path() const { return path_; }
  fs::path write(const std::string& name, const std::vector<std::byte>& data) const {
    const fs::path file = path_ / name;
    std::ofstream(file, std::ios::binary)
        .write(reinterpret_cast<const char*>(data.data()), static_cast<std::streamsize>(data.size()));
    return file;
  }

 private:
  fs::path path_;
};

}  // namespace mpt_test
